            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "For my part, I travel not to go anywhere, but to go. I travel for travel's sake. The great affair is to move.", Author = "Robert Louis Stevenson" },
