            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "A good conscience is eight parts of courage.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "We do not go to cowards for tender dealing; there is nothing so cruel as panic; the man who has least fear for his own carcase, has most time to consider others.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "To be overwise is to ossify; and the scruple-monger ends by standing stockstill.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "It is better to lose health like a spendthrift than to waste it like a miser. It is better to live and be done with it, than to die daily in the sick-room.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "By all means begin your folio; even if the doctor does not give you a year, even if he hesitates about a month, make one brave push and see what can be accomplished in a week.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Idleness, which is often becoming and even wise in the bachelor, begins to wear a different aspect when you have a wife to support.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Man is a creature who lives not upon bread alone, but principally by catchwords; and the little rift between the sexes is astonishingly widened by simply teaching one set of catchwords to the girls and another to the boys.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Falling in love is the one illogical adventure, the one thing of which we are tempted to think as supernatural, in our trite and reasonable world.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "The cruelest lies are often told in silence.", Author = "Robert Louis Stevenson" },
