            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "The difficulty of literature is not to write, but to write what you mean; not to affect your reader, but to affect him precisely as you wish.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "There is a strong feeling in favour of cowardly and prudential proverbs.", Author = "Robert Louis Stevenson" },
