            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "The time would fail me if I were to recite all the big names in history whose exploits are perfectly irrational and even shocking to the business mind.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "To hold the same views at forty as we held at twenty is to have been stupefied for a score of years, and take rank, not as a prophet, but as an unteachable brat, well birched and none the wiser.", Author = "Robert Louis Stevenson" },
