            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "All error, not merely verbal, is a strong way of stating that the current truth is incomplete.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "When the torrent sweeps the man against a boulder, you must expect him to scream, and you need not be surprised if the scream is sometimes a theory.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Shelley was a young fool; so are these cocksparrow revolutionaries. But it is better to be a fool than to be dead.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "It is better to emit a scream in the shape of a theory than to be entirely insensible to the jars and incongruities of life and take everything as it comes in a forlorn stupidity.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "For God's sake give me the young man who has brains enough to make a fool of himself!", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "As for the others, the irony of facts shall take it out of their hands, and make fools of them in downright earnest, ere the farce be over.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "To equip a dull, respectable person with wings would be but to make a parody of an angel.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Age may have one side, but assuredly Youth has the other. There is nothing more certain than that both are right, except perhaps that both are wrong.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "I suppose it is written that any one who sets up for a bit of a philosopher, must contradict himself to his very face.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "There is a sort of dead-alive, hackneyed people about, who are scarcely conscious of living except in the exercise of some conventional occupation.", Author = "Robert Louis Stevenson" },
