            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Perpetual devotion to what a man calls his business, is only to be sustained by perpetual neglect of many other things.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "There is certainly some chill and arid knowledge to be found upon the summits of formal and laborious science; but it is all round about you, and for the trouble of looking, that you will acquire the warm and palpitating facts of life.", Author = "Robert Louis Stevenson" },
