            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "People trifle with love. Now, I deny that love is a strong passion. Fear is the strong passion; it is with fear that you must trifle, if you wish to taste the intensest joys of living.", Author = "Robert Louis Stevenson" },
