            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "When things fall out opportunely for the person concerned, he is not apt to be critical about the how or why, his own immediate personal convenience seeming a sufficient reason for the strangest oddities and revolutions in our sublunary things.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "When a man is in a fair way and sees all life open in front of him, he seems to himself to make a very important figure in the world.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "It is not wonderful if his head is turned for a time. But once he is dead, were he as brave as Hercules or as wise as Solomon, he is soon forgotten.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "And perhaps this habit of much travel, and the engendering of scattered friendships, may prepare the euthanasia of ancient nations.", Author = "Robert Louis Stevenson" },
