            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "There is no foreign land; it is the traveller only that is foreign, and now and again, by a flash of recollection, lights up the contrasts of the ear.", Author = "Robert Louis Stevenson" },
