            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Wherever a man is, there will be a lie.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Though the coming of the day is still the most inspiriting, yet day's departure, also, and the return of night refresh, renew, and quiet us; and in the pastures of the dusk we stand, like cattle, exulting in the absence of the load.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "But the more he is alone with nature, the greater man and his doings bulk in the consideration of his fellow-men.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Fifteen men on the dead man's chest - Yo-ho-ho, and a bottle of rum! Drink and the devil had done for the rest - Yo-ho-ho, and a bottle of rum!", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "What is the Black Spot, Captain? That's a summons, mate.", Author = "Robert Louis Stevenson" },
