            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Let first the onion flourish there, Rose among roots, the maiden-fair, Wine-scented and poetic soul Of the capacious salad bowl.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Dear Andrew, with the brindled hair Who glory to have thrown in air, High over arm, the trembling reed, By Ale and Kail, by Till and Tweed.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Under the wide and starry sky, Dig the grave and let me lie. Glad did I live and gladly die, And I laid me down with a will.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "This be the verse you grave for me: Here he lies where he longed to be; Home is the sailor, home from sea, And the hunter home from the hill.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "My body which my dungeon is, And yet my parks and palaces: - Which is so great that there I go All the day long to and fro.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "There's just ae thing I cannae bear, An' that's my conscience.", Author = "Robert Louis Stevenson" },
