            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "The observer (poor soul, with his documents!) is all abroad. For to look at the man is but to court deception.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "We shall see the trunk from which he draws his nourishment; but he himself is above and abroad in the green dome of foliage, hummed through by winds and nested in by nightingales.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "And the true realism were that of the poets, to climb up after him like a squirrel, and catch some glimpse of the heaven for which he lives.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "For to miss the joy is to miss all. In the joy of the actors lies the sense of any action.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "We should wipe two words from our vocabulary: gratitude and charity.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "In real life, help is given out of friendship, or it is not valued; it is received from the hand of friendship, or it is resented.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "There is indeed one element in human destiny that not blindness itself can controvert: whatever else we are intended to do, we are not intended to succeed; failure is the fate allotted.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Gentleness and cheerfulness, these come before all morality; they are the perfect duties.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "If your morals make you dreary, depend upon it they are wrong.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Here lies one who meant well, tried a little, failed much: - surely that may be his epitaph of which he need not be ashamed.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "To make our idea of morality centre on forbidden acts is to defile the imagination and to introduce into our judgments of our fellow-men a secret element of gusto.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Wealth I ask not, hope nor love, Nor a friend to know me; All I ask, the heaven above And the road below me.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "The untented Kosmos my abode, I pass, a wilful stranger: My mistress still the open road And the bright eyes of danger.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "I will make you brooches and toys for your delight Of bird-song at morning and star-shine at night.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Bright is the ring of words When the right man rings them.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "In the highlands, in the country places, Where the old plain men have rosy faces, And the young fair maidens Quiet eyes.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "God, if this were enough, That I see things bare to the buff.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Trusty, dusky, vivid, true, With eyes of gold and bramble-dew, Steel-true and blade-straight, The great artificer Made my mate.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Be it granted me to behold you again in dying, Hills of home!", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "And no doubt it is easy thus to circumvent a child with catchwords, but it may be questioned how far it is effectual.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "An instinct in his breast detects the quibble, and a voice condemns it.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "He will instantly submit, privately hold the same opinion.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "For even in this simple and antique relation of the mother and the child, hypocrisies are multiplied.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Ice and iron cannot be welded.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "To be wholly devoted to some intellectual exercise is to have succeeded in life; and perhaps only in law and the higher mathematics may this devotion be maintained, suffice to itself without reaction, and find continual rewards without excitement.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "The world was not made for us; it was made for ten hundred millions of men, all different from each other and from us; there's no royal road there, we just have to sclamber and tumble.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "The commonplaces are the great poetic truths.", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Stevenson posits a single bird that consumes the centuries: \"the nightingale that devours time.\"", Author = "Robert Louis Stevenson" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Robert_Louis_Stevenson", Text = "Truth out of Tusitala spoke and pleasure out of pain.", Author = "Robert Louis Stevenson" },
        };
    }
}
